node <<'NODE'
const fs = require('node:fs')
const vm = require('node:vm')
const assert = require('node:assert/strict')
const ts = require('typescript')
const React = require('react')
const { renderToStaticMarkup } = require('react-dom/server')
const source = fs.readFileSync('app/UserStats.tsx', 'utf8')
const code = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX } }).outputText
const module = { exports: {} }
vm.runInNewContext(code, { module, exports: module.exports, require })
const UserStats = module.exports.default
const check = (users, expected) => {
  const html = renderToStaticMarkup(React.createElement(UserStats, { users }))
  for (const text of expected) assert.ok(html.includes(text), `${text} missing from ${html}`)
}
check([{ id: 1, name: 'A', isActive: true }, { id: 2, name: 'B', isActive: false }, { id: 3, name: 'C', isActive: true }], ['Active Users: 2', 'Inactive Users: 1', 'Active Percentage: 66.7%'])
check([], ['Active Users: 0', 'Inactive Users: 0', 'Active Percentage: 0.0%'])
console.log('UserStats render checks passed (mixed users and empty users)')
NODE

